#!/usr/bin/env bash
# Writes the 200 root types of LsMany.cs (R000..R199: 3 to 7 properties, all with the nested class SharedAddr) and the typed calls for them, to stdout.
# Usage: fast/many-types.sh > LsManyTypes.cs   (setup.sh does this)
set -euo pipefail
N=200
EXTRA_PROPS=("public double Amount { get; set; }" "public bool Flag { get; set; }" "public long Tick { get; set; }" "public string Note { get; set; }")
cat <<'HEAD'
// Generated by many-types.sh: the root types of LsMany.cs.
using LsMsgPack;
using System;
using System.Buffers;

public class SharedAddr { public string Street { get; set; } public int Zip { get; set; } }
HEAD
for ((i = 0; i < N; i++)); do
  props="public int Id { get; set; } public string Name { get; set; } public SharedAddr At { get; set; }"
  for ((e = 0; e < i % 5; e++)); do props="$props ${EXTRA_PROPS[$e]}"; done
  printf 'public class R%03d { %s }\n' $i "$props"
done
printf '\nstatic class Many\n{\n  internal const int N = %d;\n' $N
for ((i = 0; i < N; i++)); do
  sets="Id = $i, Name = \"n$i\", At = new SharedAddr { Street = \"s\", Zip = $i }"
  extras=("Amount = $i.5" "Flag = true" "Tick = $((i * 1000))" "Note = \"x\"")
  for ((e = 0; e < i % 5; e++)); do sets="$sets, ${extras[$e]}"; done
  printf '  static readonly R%03d V%03d = new R%03d { %s };\n' $i $i $i "$sets"
done
echo '  internal static Action<LsMsgPackSerializer, ArrayBufferWriter<byte>>[] Writers = {'
for ((i = 0; i < N; i++)); do printf '    (s, b) => s.Serialize(V%03d, b),\n' $i; done
echo '  };'
echo '  internal static Func<LsMsgPackSerializer, byte[]>[] Bytes = {'
for ((i = 0; i < N; i++)); do printf '    s => s.Serialize(V%03d),\n' $i; done
echo '  };'
echo '  internal static Func<LsMsgPackSerializer, byte[], object>[] Readers = {'
for ((i = 0; i < N; i++)); do printf '    (s, d) => s.Deserialize<R%03d>(d),\n' $i; done
echo '  };'
echo '}'
